// rewardSop divisor (fixed at rain start):
// sops[rainStart][well] += amount * SOP_PRECISION / s.sys.rain.roots;   // L325, rain.roots set once at L74

// handleRainAndSops only snapshots rainRoots when STRICTLY greater:
if (s.sys.season.rainStart > lastUpdate) {            // L124
    s.accts[account].lastRain = s.sys.season.rainStart;
    s.accts[account].sop.rainRoots = s.accts[account].roots; // L126
}

// balanceOfPlenty fallback uses LIVE roots, not the snapshot:
if (s.sys.season.lastSop > s.accts[account].lastUpdate) {              // L178
    uint256 plentyPerRoot = s.sys.sop.sops[s.sys.season.lastSop][well].sub(previousPPR);
    plenty = plenty.add(plentyPerRoot.mul(s.accts[account].roots).div(C.SOP_PRECISION)); // L180 LIVE roots
}

if (s.sys.season.rainStart > lastUpdate) {
    s.accts[account].lastRain = s.sys.season.rainStart;
    s.accts[account].sop.rainRoots = s.accts[account].roots; // captured at FIRST mow during rain, may include post-rain-start germinated roots
}
